import {HomeManager} from './homes.js';
import {CageLayout,ITEMS,canvasPoint} from './layout.js';
import {SimulationEngine,InteractionSystem,EventJournal,LABELS,VERSION,CHARACTERS,HealthSystem,COATS,petText,PlaySystem} from './model.js';
import {SaveManager} from './save.js';
import {Renderer} from './renderer.js';
const $=id=>document.getElementById(id);let storage;try{storage=window.localStorage;}catch{storage={getItem(){throw Error('blocked');},setItem(){throw Error('blocked');}};}
const loaded=HomeManager.load(storage);let manager=loaded.manager,engine=new SimulationEngine(manager.active.state),saveBlocked=!!loaded.blocked;let hidden=document.hidden,last=performance.now(),savedAt=0,paintedAt=0,refreshedAt=0,toastTimer;let editing=null,toyPointer=null;
const away=manager.resumeAll().get(manager.world.activeId);const renderer=new Renderer($('world'));try{renderer.useWorld=storage.getItem('hamster-life-view')!=='2d';}catch{}const needs=[['hunger','Сытость',true],['thirst','Вода',true],['energy','Энергия'],['health','Здоровье']];
for(const [key,label] of needs){const row=document.createElement('div');row.className='meter';row.innerHTML=`<span>${label}</span><div class="track"><div class="fill" id="bar-${key}"></div></div><em id="val-${key}"></em>`;$('needs').append(row);}
function toast(text){$('toast').textContent=text;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),5500);}
function save(){if(saveBlocked){$('save-status').textContent='⚠ Автосохранение остановлено. Экспортируйте данные в настройках.';return;}const ok=manager.save(storage);$('save-status').textContent=ok?'✓ Прогресс сохранён на этом устройстве':'⚠ Сохранение недоступно. Экспортируйте данные.';}
function refresh(){const s=engine.state;$('render-mode').textContent=editing?'Планировка · вид спереди':renderer.renderMode;$('view-mode').textContent=!editing&&renderer.useWorld&&renderer.habitat3d&&!renderer.model3d?.lost?'Клетка: 3D':'Клетка: 2D';$('view-mode').disabled=!!editing||renderer.loading3d||!renderer.habitat3d||!!renderer.model3d?.lost;$('world').classList.toggle('playing',s.play.remaining>0&&!editing);if(s.play.remaining<=0)toyPointer=null;$('pet-name').textContent=s.name;$('scene-title').textContent=s.name.toLocaleUpperCase('ru-RU')+' · '+manager.world.activeId.replace('home','ДОМИК ');$('home-count').textContent=manager.world.homes.length+'/3';for(const [key,,invert]of needs){const v=Math.round(invert?100-s.needs[key]:s.needs[key]);$('bar-'+key).style.width=v+'%';$('bar-'+key).style.background=v<25?'#c38c6c':'#8f9e73';$('val-'+key).textContent=v+'%';}
 const report=HealthSystem.report(s);const wellnessText=report.title+(s.illness.kind?(report.recovering?' · Восстанавливается':' · Нужен уход'):'');if($('wellness-status').textContent!==wellnessText)$('wellness-status').textContent=wellnessText;$('wellness-status').classList.toggle('needs-care',!!s.illness.kind);$('behavior').textContent=editing?'Планировка · '+ITEMS[editing.selected].name:s.name+' '+LABELS[s.pet.state];$('cage-summary').textContent=`Гнездо ${Math.round(s.cage.nest)}% · Тайник ${Math.round(s.cage.stash)} · В щёчках ${Math.round(s.pet.carry)}`;$('bond-summary').textContent=`${CHARACTERS[s.bond.character].name} · Доверие ${Math.round(s.bond.trust)}%`;$('scene-clock').textContent=s.play.remaining>0?'Мячик · '+Math.ceil(s.play.remaining)+' с':`День ${1+Math.floor(s.elapsed/86400)} · ${s.alive?'Уютно дома':'Память о питомце'}`;$('mode-label').textContent=s.mode==='child'?'● Детский режим':'● Реалистичный режим';
 for(const[k,label]of [['food','Запас'],['water','Запас'],['clean','Чистота']])$(k+'-stock').textContent=label+' '+Math.round(s.cage[k])+'%';document.querySelectorAll('[data-action]').forEach(b=>b.disabled=!s.alive||!!editing);
 for(const id of ['settings','journal','health','homes','inspect-pet'])$(id).disabled=!!editing;$('edit-cage').disabled=!s.alive||!!editing||s.play.remaining>0;
 $('tip-text').textContent=petText(s,s.illness.kind?report.advice:s.needs.health<50?'Пончику нужен уход. Проверьте воду, корм и чистоту клетки. Подробности — в разделе здоровья.':s.pet.state==='sleep'?'Пончик отдыхает в домике. Дайте ему спокойно поспать: так он восстанавливает энергию.':'Пончик обустраивает гнездо и прячет корм в домике. Общайся с ним тихо и давай время отдохнуть.');
}
function open(title){$('modal-title').textContent=title;$('modal-body').replaceChildren();$('modal').showModal();return $('modal-body');}
function paragraph(parent,text,cls){const p=document.createElement('p');p.textContent=text;if(cls)p.className=cls;parent.append(p);return p;}
function button(parent,text,fn){const b=document.createElement('button');b.textContent=text;b.onclick=fn;parent.append(b);return b;}
$('modal').addEventListener('close',()=>{renderer.inspector=null;if(renderer.model3d){renderer.model3d.canvas.width=renderer.model3d.canvas.height=256;}});
$('view-mode').onclick=()=>{renderer.useWorld=!renderer.useWorld;try{storage.setItem('hamster-life-view',renderer.useWorld?'3d':'2d');}catch{}refresh();};
$('inspect-pet').onclick=()=>{const body=open('Рассмотреть · '+engine.state.name);const canvas=document.createElement('canvas');canvas.width=canvas.height=420;canvas.style.cssText='display:block;width:100%;max-width:420px;aspect-ratio:1;margin:auto;border-radius:18px;touch-action:none';canvas.setAttribute('aria-label','Трёхмерная модель хомячка. Проведите пальцем для вращения.');body.append(canvas);
 const viewer={canvas,angle:.5,action:'',drag:null};renderer.inspector=viewer;if(renderer.model3d)renderer.model3d.canvas.width=renderer.model3d.canvas.height=384;
 paragraph(body,'Проведи пальцем по хомячку, чтобы повернуть его. Это та же 3D-модель, которая живёт в клетке.','note');
 const label=document.createElement('label');label.textContent='Поворот';const slider=document.createElement('input');slider.type='range';slider.min=-180;slider.max=180;slider.value=29;slider.style.width='100%';slider.setAttribute('aria-label','Повернуть хомячка');slider.oninput=()=>{viewer.angle=Number(slider.value)*Math.PI/180;};label.append(slider);body.append(label);
 const motion=document.createElement('select');motion.setAttribute('aria-label','Пример движения 3D-модели');for(const [value,text]of [['','Как сейчас в игре'],['walk','Показать ходьбу'],['eat','Показать еду'],['drink','Показать питьё'],['groom','Показать умывание'],['sleep','Показать сон']]){const option=document.createElement('option');option.value=value;option.textContent=text;motion.append(option);}motion.onchange=()=>{viewer.action=motion.value;};body.append(motion);paragraph(body,'Примеры движений только показывают модель и не меняют состояние питомца.','note');
 canvas.addEventListener('pointerdown',e=>{if(viewer.drag||!e.isPrimary)return;viewer.drag={id:e.pointerId,x:e.clientX,angle:viewer.angle};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(viewer.drag?.id!==e.pointerId)return;viewer.angle=viewer.drag.angle+(e.clientX-viewer.drag.x)*.012;slider.value=Math.atan2(Math.sin(viewer.angle),Math.cos(viewer.angle))*180/Math.PI;});const finish=e=>{if(viewer.drag?.id===e.pointerId){viewer.drag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);}};canvas.addEventListener('pointerup',finish);canvas.addEventListener('pointercancel',finish);canvas.addEventListener('lostpointercapture',finish);
};
$('close-modal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close();}});
function interactionMenu(){const s=engine.state,body=open('Побыть рядом · '+s.name);paragraph(body,'Можно тихо поговорить или предложить мячик. Питомцу не нужно играть, если он устал или плохо себя чувствует.','note');button(body,'Тихо поговорить',()=>{const text=InteractionSystem.act(engine.state,'pet');$('modal').close();refresh();save();toast(petText(engine.state,text));});
 if(s.play.remaining>0){paragraph(body,'Мячик уже в клетке. Перемещайте его касанием подстилки или пальцем.');button(body,'Закончить игру',()=>{PlaySystem.end(engine.state);$('modal').close();refresh();save();toast('Мячик убран. Можно отдохнуть.');});}
 else{const ready=PlaySystem.canStart(s);paragraph(body,ready.message);const start=button(body,'Поиграть с мячиком',()=>{const result=PlaySystem.start(engine.state);if(result.ok)$('modal').close();refresh();save();toast(result.message);});start.disabled=!ready.ok;}
}
for(const b of document.querySelectorAll('[data-action]'))b.onclick=()=>{if(b.dataset.action==='pet'){interactionMenu();return;}toast(petText(engine.state,InteractionSystem.act(engine.state,b.dataset.action)));refresh();save();};
$('journal').onclick=()=>{const body=open('Дневник маленькой жизни');for(const entry of [...engine.state.journal].reverse()){const row=document.createElement('div');row.className='entry';const time=document.createElement('time');time.textContent=new Date(entry.at).toLocaleString('ru-RU');row.append(time,document.createTextNode(entry.text));body.append(row);}};
$('health').onclick=()=>{const s=engine.state,n=s.needs,body=open('Самочувствие · '+s.name);paragraph(body,`Здоровье: ${Math.round(n.health)}%. Возраст в игре: ${Math.floor(s.age/86400)} дней. Стресс: ${Math.round(n.stress)}%.`);paragraph(body,`Характер: ${CHARACTERS[s.bond.character].name}. Доверие: ${Math.round(s.bond.trust)}%. Уют гнезда: ${Math.round(s.cage.nest)}%. В тайнике ${Math.round(s.cage.stash)} единиц корма.`);const report=HealthSystem.report(s);paragraph(body,petText(s,report.title));paragraph(body,petText(s,report.detail));paragraph(body,petText(s,report.advice));if(s.illness.kind)paragraph(body,`Тяжесть недомогания: ${report.severity}%. ${report.recovering?'Условия для восстановления есть. Пончику нужно время.':'Сейчас условия для восстановления не выполнены: проверьте питание, воду, чистоту, энергию и стресс.'}`);paragraph(body,'Характер влияет на скорость движения и выбор активности. Общение повышает доверие и помогает успокоиться; тревожить спящего питомца не стоит. Доверие не снижается за отсутствие ребёнка. Между разговорами дайте ему хотя бы 30 секунд.','note');const reasons=[];if(n.hunger>70)reasons.push('Питомец голоден. Наполните кормушку.');if(n.thirst>70)reasons.push('Питомец хочет пить. Проверьте поилку.');if(s.cage.clean<30)reasons.push('Пора заменить подстилку.');if(n.energy<25)reasons.push('Ему нужен сон в домике.');if(s.mode==='realistic'&&s.age>90*86400)reasons.push('Включено игровое старение: здоровье постепенно снижается.');if(!s.alive)reasons.push('Жизнь завершилась: '+s.deathReason+'.');for(const reason of reasons.length?reasons:['Сейчас дополнительных причин для тревоги не обнаружено.'])paragraph(body,reason);paragraph(body,'Это условная игровая модель, не ветеринарная диагностика. В игре недомогание накапливается из-за длительных проблем ухода и проходит постепенно при хороших условиях. Лекарств и точных ветеринарных прогнозов здесь нет.','note');};
function download(single=false){manager.resumeAll();last=performance.now();const a=document.createElement('a');const u=URL.createObjectURL(new Blob([JSON.stringify(single?engine.state:manager.world,null,2)],{type:'application/json'}));a.href=u;a.download=single?'hamster-life-pet.json':'hamster-life-homes.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('settings').onclick=()=>{const body=open('Настройки · '+engine.state.name);const rename=document.createElement('input');rename.type='text';rename.value=engine.state.name;rename.maxLength=24;rename.setAttribute('aria-label','Имя текущего питомца');rename.style.cssText='width:100%;min-height:48px;font:inherit;padding:10px';body.append(rename);button(body,'Сохранить имя',()=>{try{manager.rename(rename.value);refresh();save();toast('Имя сохранено.');}catch(error){toast(error.message);}});paragraph(body,'Режим заботы для текущего питомца');const select=document.createElement('select');select.setAttribute('aria-label','Режим заботы');for(const [v,t]of [['child','Детский — здоровье не ниже 25%'],['realistic','Реалистичный — возможна смерть']]){const o=document.createElement('option');o.value=v;o.textContent=t;select.append(o);}select.value=engine.state.mode;
 select.onchange=()=>{if(select.value==='realistic'&&!confirm('В реалистичном режиме питомец может умереть из-за отсутствия ухода или игрового старения, в том числе пока игра закрыта. Включить?')){select.value=engine.state.mode;return;}engine.state.mode=select.value;EventJournal.add(engine.state,'Режим изменён: '+(select.value==='child'?'детский':'реалистичный'));refresh();save();};body.append(select);paragraph(body,'После закрытия жизнь рассчитывается при следующем открытии. Не нужно держать приложение в фоне. Один реальный день равен одному игровому. За одно возвращение учитывается не больше 30 дней.','note');
 button(body,'Скачать все жилища',()=>download());button(body,'Скачать текущего питомца',()=>download(true));paragraph(body,'Восстановить из файла: мир заменит все жилища, одиночный питомец — только текущего.');const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.setAttribute('aria-label','Импорт сохранения');input.onchange=async()=>{const f=input.files[0];if(!f)return;try{if(f.size>1e6)throw Error('large');const raw=JSON.parse(await f.text());const incoming=HomeManager.validate(raw);const all=raw.version===2;if(!confirm(all?'Заменить все жилища выбранным резервным миром?':'Заменить жизнь только в текущем домике? Остальные питомцы останутся.'))return;if(all){manager=new HomeManager(incoming);engine=manager.activate(manager.world.activeId);}else{engine=manager.replaceActive(raw);manager.resumeAll();}saveBlocked=false;toyPointer=null;renderer.visualX=null;last=performance.now();refresh();save();$('modal').close();toast('Сохранение восстановлено.');}catch{toast('Не удалось прочитать файл: сохранение повреждено или имеет другую версию.');}};body.append(input);
 paragraph(body,'Для офлайн-запуска откройте игру по HTTPS и дождитесь сообщения «Офлайн-версия сохранена». Затем можно добавить её на главный экран через меню браузера. Встроенный браузер ChatGPT может ограничивать установку; используйте Chrome.','note');
 paragraph(body,`HAMSTER LIFE ${VERSION}. Без платных API, рекламы и покупок. Данные находятся в браузере этого устройства. Очистка данных браузера удалит прогресс; сохраните резервный файл. Предметы перемещаются через кнопку «Предметы» под клеткой. В планировке жизнь отображается на паузе, прошедшее время рассчитывается после выхода.`,'note');};
function useHome(id){engine=manager.activate(id);toyPointer=null;renderer.visualX=null;last=performance.now();refresh();save();$('modal').close();toast('Открыт домик: '+engine.state.name);}
function choice(parent,label,options,value){const title=document.createElement('label');title.textContent=label;const select=document.createElement('select');select.setAttribute('aria-label',label);for(const [key,item]of Object.entries(options)){const option=document.createElement('option');option.value=key;option.textContent=item.name;select.append(option);}select.value=value;parent.append(title,select);return select;}
$('homes').onclick=()=>{
 manager.resumeAll();last=performance.now();const body=open('Отдельные жилища');paragraph(body,'У каждого питомца своя клетка и своя жизнь. Пока вы смотрите другой домик, время продолжает учитываться.','note');
 for(const home of manager.world.homes){const state=home.state,card=document.createElement('section');card.className='home-card';const title=document.createElement('h3');title.textContent=home.id.replace('home','Домик ')+' · '+state.name;card.append(title);paragraph(card,COATS[state.coat].name+' · '+CHARACTERS[state.bond.character].name+' · '+(state.mode==='child'?'Детский режим':'Реалистичный режим'));paragraph(card,state.alive?'Здоровье '+Math.round(state.needs.health)+'% · '+petText(state,HealthSystem.report(state).title):'История завершённой жизни сохранена');button(card,home.id===manager.world.activeId?'Выбранный домик':'Открыть домик',()=>useHome(home.id));body.append(card);}
 if(saveBlocked){paragraph(body,'Создание заблокировано до восстановления сохранения. Откройте настройки и импортируйте резервный файл.','form-error');return;}
 if(manager.world.homes.length>=HomeManager.limit){paragraph(body,'Все три жилища заняты. Существующие питомцы и их истории сохраняются.','note');return;}
 const form=document.createElement('div');form.className='pet-form';const heading=document.createElement('h3');heading.textContent='Новый питомец';form.append(heading);const label=document.createElement('label');label.textContent='Имя';const name=document.createElement('input');name.type='text';name.maxLength=24;name.value=manager.world.homes.length===1?'Снежок':'Бублик';name.setAttribute('aria-label','Имя нового питомца');form.append(label,name);const coat=choice(form,'Окрас (визуальный вариант)',COATS,manager.world.homes.length===1?'snow':'gray');const character=choice(form,'Характер',CHARACTERS,'curious');paragraph(form,'Каждый новый питомец получает отдельную клетку и детский режим. Характер влияет на движение и выбор занятий. Окрас меняет только внешний вид.','note');const error=document.createElement('p');error.className='form-error';error.setAttribute('role','status');form.append(error);button(form,'Поселить в новом домике',()=>{try{const home=manager.add({name:name.value,coat:coat.value,character:character.value});useHome(home.id);}catch(e){error.textContent=e.message;}});body.append(form);
};

const world=$('world');
function editorHint(text){if($('layout-hint').textContent!==text)$('layout-hint').textContent=text;}
function moveItem(x){if(!editing)return;const result=CageLayout.move(editing.draft,editing.selected,x);editing.draft=result.layout;editing.invalid=!result.ok;editing.candidate=result.candidate;$('layout-done').disabled=!result.ok;editorHint(result.ok?'Место свободно. Нажмите «Готово», чтобы сохранить.':result.message);}
$('edit-cage').onclick=()=>{
 if(!engine.state.alive||editing||engine.state.play.remaining>0)return;
 save();editing={draft:CageLayout.snapshot(engine.state.cage),selected:'home',invalid:false,candidate:null,drag:null};
 $('layout-item').value='home';$('layout-done').disabled=false;$('layout-tools').hidden=false;world.classList.add('editing');editorHint('Предметы показаны спереди. Перетащите пальцем или выберите место стрелками. После выхода вернётся ваш обычный вид.');refresh();
};
function finishLayout(commit){
 if(!editing)return;
 const draft=editing.draft;
 if(commit&&(editing.invalid||!CageLayout.validate(draft).ok)){editorHint('Выберите свободное место.');return;}
 engine.resume();
 const applied=commit&&CageLayout.commit(engine.state,draft);
 if(applied)EventJournal.add(engine.state,'Вы переставили предметы. Пончик осваивает новую планировку.');
 editing=null;$('layout-tools').hidden=true;world.classList.remove('editing');last=performance.now();refresh();save();
 toast(applied?'Расположение сохранено. Пончик сам найдёт кормушку и домик.':commit?'Планировка не изменена: жизнь питомца завершилась.':'Перестановка отменена.');
}
$('layout-done').onclick=()=>finishLayout(true);$('layout-cancel').onclick=()=>finishLayout(false);
$('layout-item').onchange=()=>{if(editing){if(editing.drag){$('layout-item').value=editing.selected;return;}editing.selected=$('layout-item').value;editing.invalid=false;$('layout-done').disabled=false;refresh();}};
$('layout-left').onclick=()=>{if(editing)moveItem(editing.draft[editing.selected]-10);};$('layout-right').onclick=()=>{if(editing)moveItem(editing.draft[editing.selected]+10);};
function pointerPoint(e){return canvasPoint(e.clientX,e.clientY,world.getBoundingClientRect(),getComputedStyle(world).objectFit);}
world.addEventListener('pointerdown',e=>{
 if(!editing||editing.drag||!e.isPrimary)return;
 const point=pointerPoint(e);if(!point)return;e.preventDefault();
 const key=CageLayout.hit(editing.draft,point.x,point.y);if(key)editing.selected=key;
 $('layout-item').value=editing.selected;
 editing.drag={id:e.pointerId,offset:key?point.x-editing.draft[key]:0,before:{...editing.draft}};
 world.setPointerCapture(e.pointerId);if(!key)moveItem(point.x);refresh();
});
world.addEventListener('pointermove',e=>{if(!editing||editing.drag?.id!==e.pointerId)return;const point=pointerPoint(e);if(point){e.preventDefault();moveItem(point.x-editing.drag.offset);}});
world.addEventListener('pointerup',e=>{if(!editing||editing.drag?.id!==e.pointerId)return;const point=pointerPoint(e);if(point)moveItem(point.x-editing.drag.offset);editing.drag=null;if(world.hasPointerCapture(e.pointerId))world.releasePointerCapture(e.pointerId);});
function cancelDrag(e){if(!editing||editing.drag?.id!==e.pointerId)return;editing.draft=editing.drag.before;editing.drag=null;editing.invalid=false;$('layout-done').disabled=false;editorHint('Движение отменено. Можно попробовать ещё раз.');}
world.addEventListener('pointercancel',cancelDrag);world.addEventListener('lostpointercapture',cancelDrag);
window.addEventListener('keydown',e=>{if(editing&&e.key==='Escape')finishLayout(false);});

function moveToy(e){if(editing||engine.state.play.remaining<=0)return;const point=pointerPoint(e);if(point)PlaySystem.move(engine.state,point.x);}
world.addEventListener('pointerdown',e=>{if(editing||engine.state.play.remaining<=0||!e.isPrimary)return;e.preventDefault();toyPointer=e.pointerId;world.setPointerCapture(e.pointerId);moveToy(e);});
world.addEventListener('pointermove',e=>{if(toyPointer!==e.pointerId||editing)return;e.preventDefault();moveToy(e);});
function endToyPointer(e){if(toyPointer!==e.pointerId)return;toyPointer=null;if(world.hasPointerCapture(e.pointerId))world.releasePointerCapture(e.pointerId);}
world.addEventListener('pointerup',endToyPointer);world.addEventListener('pointercancel',endToyPointer);world.addEventListener('lostpointercapture',endToyPointer);

function frame(now){if(!hidden){if(!editing){const dt=(now-last)/1000;if(dt>2)engine.resume();else engine.advance(dt);}if(now-savedAt>5000){save();savedAt=now;}if(now-refreshedAt>500){refresh();refreshedAt=now;}}last=now;if(!hidden&&now-paintedAt>32){renderer.draw(editing?{...engine.state,cage:{...engine.state.cage,...editing.draft}}:engine.state,now,editing);renderer.inspect(engine.state,now);paintedAt=now;}requestAnimationFrame(frame);}
document.addEventListener('visibilitychange',()=>{hidden=document.hidden;if(hidden)save();else{if(!editing)manager.resumeAll();last=performance.now();refresh();save();}});window.addEventListener('pagehide',save);refresh();save();requestAnimationFrame(frame);
if(loaded.message)toast(loaded.message);else if(away.seconds>60)toast(`С возвращением! Рассчитано ${Math.round(away.seconds/60)} мин. жизни. Подробности в дневнике.`);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').then(async reg=>{await navigator.serviceWorker.ready;const worker=reg.active||reg.installing||reg.waiting;if(worker?.state==='activated')toast('Офлайн-версия сохранена. Можно играть без интернета.');else worker?.addEventListener('statechange',()=>{if(worker.state==='activated')toast('Офлайн-версия сохранена. Можно играть без интернета.');});}).catch(()=>toast('Офлайн-кэш недоступен. Для запуска сейчас нужен интернет.'));
